#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
using namespace std;

int main(){
double position=1.2,momentum=0.4,stepSize=0.1;
double oldEnergy=(position*position+momentum*momentum)/2;
momentum-=stepSize*position/2;
for(int step=0;step<10;step++){
    position+=stepSize*momentum;
    if(step<9)momentum-=stepSize*position;
}
momentum-=stepSize*position/2;
double newEnergy=(position*position+momentum*momentum)/2;
cout<<"Position "<<position<<" accept "<<min(1.0,exp(oldEnergy-newEnergy))<<endl;
    return 0;
}

