#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
using namespace std;

int main(){
vector<vector<double>> probability={{0.7,0.3},{0.2,0.8},
    {0.4,0.6},{0.9,0.1}};
vector<int> token={0,1,1,0};
double joint=1,loss=0;
for(int t=0;t<int(token.size());t++){
    double p=probability[t][token[t]];
    joint*=p;
    loss-=log(p);
}
cout<<"Joint "<<joint<<" NLL "<<loss<<endl;
    return 0;
}

