#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
using namespace std;

int main(){
vector<double> token={1,2,3,4};
for(int t=0;t<int(token.size());t++){
    vector<double> score;
    for(int j=0;j<=t;j++)score.push_back(token[t]*token[j]/sqrt(2.0));
    double largest=*max_element(score.begin(),score.end()),denom=0;
    for(double value:score)denom+=exp(value-largest);
    double output=0;
    for(int j=0;j<=t;j++)
        output+=exp(score[j]-largest)*token[j]/denom;
    cout<<t<<" "<<output<<endl;
}
    return 0;
}

