#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
using namespace std;

int main(){
struct Edge{int from,to;};
vector<Edge> edges={{0,2},{1,2},{2,3},{0,3}};
vector<double> feature={1,2,5,7};
for(int node=0;node<int(feature.size());node++){
    double total=0;int count=0;
    for(const Edge& edge:edges)if(edge.to==node){
        total+=feature[edge.from];
        count++;
    }
    cout<<node<<" "<<(count?total/count:0)<<endl;
}
    return 0;
}

