#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
using namespace std;

int main(){
vector<double> input={2,4};
double encoder[2]={0.25,0.5},latent=0;
for(int i=0;i<2;i++)latent+=encoder[i]*input[i];
vector<double> decoder={1.2,1.8};
double mse=0;
for(int i=0;i<2;i++){
    double predicted=decoder[i]*latent;
    mse+=pow(predicted-input[i],2)/input.size();
    cout<<i<<" "<<predicted<<endl;
}
cout<<"Reconstruction MSE "<<mse<<endl;
    return 0;
}
